  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number' },
          b: { type: 'number' },
          operation: { type: 'string', enum: ['add', 'subtract', 'multiply', 'divide'] }
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate args is an object
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }

  // Check for missing fields
  if (!('a' in args)) throw new Error('Missing required field: a');
  if (!('b' in args)) throw new Error('Missing required field: b');
  if (!('operation' in args)) throw new Error('Missing required field: operation');

  const { a, b, operation } = args;

  // Check for extra fields
  const allowed = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  // Validate types
  if (typeof a !== 'number' || Number.isNaN(a)) {
    throw new Error('a must be a number');
  }
  if (typeof b !== 'number' || Number.isNaN(b)) {
    throw new Error('b must be a number');
  }

  // Validate operation
  const ops = new Set(['add', 'subtract', 'multiply', 'divide']);
  if (typeof operation !== 'string' || !ops.has(operation)) {
    throw new Error('Unsupported operation');
  }

  let result;
  switch (operation) {
    case 'add':
      result = a + b;
      break;
    case 'subtract':
      result = a - b;
      break;
    case 'multiply':
      result = a * b;
      break;
    case 'divide':
      if (b === 0) {
        throw new Error('Division by zero');
      }
      result = a / b;
      break;
  }

  return { content: [{ type: 'text', text: String(result) }] };
}
